-- =====================================================================
-- IDTNPR - Dados iniciais do site (o que as migrations insere_* fazem)
-- MySQL 5.7+ / 8. Nao escolhe banco (sem CREATE DATABASE nem USE): age no
-- banco selecionado na conexao.
--
-- POR QUE EXISTE: o servidor nao tem terminal, entao ninguem roda
-- "php artisan migrate". Os outros .sql so criam as tabelas (vazias); sem
-- estes dados as paginas /projetos, /editais, /transparencia e a diretoria
-- da pagina Institucional aparecem sem conteudo.
--
-- ORDEM: rode DEPOIS de criar as tabelas (e, se a tabela projetos for da
-- versao antiga, depois do idtnpr_corrige_projetos_mysql.sql).
-- Pode rodar mais de uma vez: cada linha so entra se o id ainda nao existir.
-- Depois de rodar, tudo e editado pelo painel (/adm).
-- Texto das paginas (site_texts) nao precisa: o site usa o texto padrao e o
-- painel cria a tabela de textos na primeira visita a /adm/conteudo.
-- =====================================================================

SET NAMES utf8mb4;

